<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { CopyDocument, Collection, DataAnalysis, FolderOpened, Monitor, Picture, Setting, Upload, VideoPlay, Files, Connection, RefreshRight, Refresh, Search, Plus, Delete, Edit, Download, MagicStick, User, Key, ArrowDown } from '@element-plus/icons-vue'
import api from './api'

type Page = 'dashboard'|'assets'|'random'|'categories'|'providers'|'profiles'|'jobs'|'backup'|'users'|'settings'
const loggedIn = ref(!!localStorage.getItem('vpl_token')); const loginForm = reactive({ username: 'admin', password: 'change-this-password' }); const loading = ref(false)
const currentUser = ref<any>(JSON.parse(localStorage.getItem('vpl_user') || '{"username":"管理员","role":"admin"}')); const page = ref<Page>('dashboard'); const categories = ref<any[]>([]); const assets = ref<any[]>([]); const total = ref(0); const providers = ref<any[]>([]); const profiles = ref<any[]>([]); const jobs = ref<any[]>([]); const users = ref<any[]>([]); const jobTimer = ref<number | undefined>(); const avatarRef = ref<HTMLInputElement>(); const avatarFile = ref<File | null>(null)
const jobProgress = reactive({ total: 0, completed: 0, active: 0, failed: 0, percentage: 0, current: null as any })
const savedCategoryId = Number(localStorage.getItem('vpl_asset_category_id') || 0)
const filters = reactive({ category_id: Number.isInteger(savedCategoryId) && savedCategoryId > 0 ? savedCategoryId : undefined, search: '', status: '' }); const drawer = ref(false); const selected = ref<any>(null); const uploadRef = ref<HTMLInputElement>(); const folderRef = ref<HTMLInputElement>(); const contentRef = ref<HTMLElement>(); const assetsLoading = ref(false); const assetsPage = ref(1); const assetsHasMore = ref(true); const assetsPageSize = 60
const uploadForm = reactive({ category_id: undefined as number|undefined, provider_id: undefined as number|undefined, model_name: '', prompt_profile_id: undefined as number|undefined }); const uploadFiles = ref<File[]>([]); const randomForm = reactive({ category_ids: [] as number[], count: 1, seed: 0 }); const randomItems = ref<any[]>([])
const dialogs = reactive({ category: false, provider: false, profile: false, user: false, comfyKey: false }); const categoryForm = reactive({ id: 0, name: '', description: '', sort_order: 0, enabled: true }); const providerForm = reactive({ id: 0, name: '', base_url: 'http://host.docker.internal:1234/v1', api_key: '', models: [] as string[], enabled: true }); const profileForm = reactive({ id: 0, name: '', system_prompt: '', temperature: .2, max_tokens: 1200, enabled: true }); const userForm = reactive({ id: 0, username: '', password: '', role: 'user', enabled: true, avatar_url: '', category_ids: [] as number[] }); const settingsForm = reactive({ comfyui_api_key: '', masked: '' }); const comfyKeys = ref<any[]>([]); const comfyKeyForm = reactive({ id: 0, name: '', key: '', enabled: true, category_ids: [] as number[] })
const nav = [{id:'dashboard',label:'仪表盘',icon:Monitor},{id:'assets',label:'素材库',icon:Picture},{id:'random',label:'随机提示词',icon:MagicStick},{id:'categories',label:'分类管理',icon:Collection},{id:'providers',label:'AI 服务管理',icon:Connection,admin:true},{id:'profiles',label:'系统提示词模板',icon:Files,admin:true},{id:'jobs',label:'分析任务',icon:DataAnalysis,admin:true},{id:'backup',label:'导入导出',icon:FolderOpened,admin:true},{id:'users',label:'账号管理',icon:User,admin:true},{id:'settings',label:'系统设置',icon:Setting,admin:true}]
const visibleNav = computed(() => nav.filter(item => !item.admin || currentUser.value.role === 'admin'))
const currentLabel = computed(() => visibleNav.value.find(n=>n.id===page.value)?.label || '')
const availableUploadModels = computed(() => providers.value.find(p=>p.id===uploadForm.provider_id)?.models || [])
const currentJobs = computed(() => {
  const seen = new Set<number>()
  return jobs.value.filter((job:any) => {
    if(seen.has(job.asset_id))return false
    seen.add(job.asset_id)
    return true
  })
})
const failedJobs = computed(() => currentJobs.value.filter((job:any)=>job.status==='failed'))
const adminPages = new Set<Page>(['providers','profiles','jobs','backup','users','settings'])
watch(() => currentUser.value.role, role => { if(role !== 'admin' && adminPages.has(page.value)) page.value='dashboard' })
const imageUrl = (u:string) => u?.startsWith('http') ? u : u
async function login(){ loading.value=true; try { const {data}=await api.post('/api/v1/auth/login', loginForm); localStorage.setItem('vpl_token',data.access_token); currentUser.value={username:data.username,role:data.role,user_id:data.user_id,avatar_url:data.avatar_url,category_ids:data.category_ids}; localStorage.setItem('vpl_user',JSON.stringify(currentUser.value)); loggedIn.value=true; await bootstrap() } catch(e:any){ ElMessage.error(e.response?.data?.detail || '登录失败') } finally {loading.value=false} }
function logout(){ localStorage.removeItem('vpl_token'); localStorage.removeItem('vpl_user'); if(jobTimer.value)window.clearInterval(jobTimer.value); page.value='dashboard'; loggedIn.value=false }
function handleAuthExpired(){ if(loggedIn.value){ logout(); ElMessage.warning('登录已过期，请重新登录') } }
async function bootstrap(){ await Promise.allSettled([loadCategories(),loadProviders(),loadProfiles(),loadUsers(),loadSettings(),loadJobs()]); await loadAssets(); if(!jobTimer.value) jobTimer.value=window.setInterval(()=>loadJobs(),4000) }
async function loadCategories(){
  categories.value=(await api.get('/api/v1/categories')).data
  if(filters.category_id && !categories.value.some(category=>category.id===filters.category_id)){
    filters.category_id=undefined
    localStorage.removeItem('vpl_asset_category_id')
  }
}
async function loadProviders(){ providers.value=(await api.get('/api/v1/providers')).data }
async function loadProfiles(){ profiles.value=(await api.get('/api/v1/prompt-profiles')).data }
async function loadAssets(reset=true){
  if(assetsLoading.value)return
  if(reset){ assetsPage.value=1; assetsHasMore.value=true }
  if(!assetsHasMore.value)return
  assetsLoading.value=true
  try {
    const {data}=await api.get('/api/v1/assets',{params:{...filters,page:assetsPage.value,page_size:assetsPageSize}})
    if(reset)assets.value=data.items
    else assets.value.push(...data.items)
    total.value=data.total
    assetsPage.value=data.page+1
    assetsHasMore.value=assets.value.length<data.total
  } finally { assetsLoading.value=false }
}
function changeAssetCategory(value?:number){
  if(value===undefined||value===null||value==='')localStorage.removeItem('vpl_asset_category_id')
  else localStorage.setItem('vpl_asset_category_id',String(value))
  loadAssets()
}
function handleContentScroll(e:Event){
  if(page.value!=='assets'||assetsLoading.value||!assetsHasMore.value)return
  const element=e.currentTarget as HTMLElement
  if(element.scrollHeight-element.scrollTop-element.clientHeight<500)loadAssets(false)
}
async function loadJobs(){ try { jobs.value=(await api.get('/api/v1/jobs')).data; const current=currentJobs.value; jobProgress.total=current.length; jobProgress.completed=current.filter((j:any)=>j.status==='completed').length; jobProgress.active=current.filter((j:any)=>['pending','processing'].includes(j.status)).length; jobProgress.failed=current.filter((j:any)=>j.status==='failed').length; const percent=jobProgress.total?Math.floor(jobProgress.completed/jobProgress.total*100):0; jobProgress.percentage=jobProgress.failed?Math.min(percent,99):percent; jobProgress.current=current.find((j:any)=>j.status==='processing') || current.find((j:any)=>j.status==='pending') || null } catch {} }
async function reanalyzeJob(job:any){ try { await api.post(`/api/v1/assets/${job.asset_id}/reanalyze`); ElMessage.success(`已重新加入分析：${job.original_filename || `素材 #${job.asset_id}`}`); await Promise.all([loadJobs(),loadAssets()]) } catch(e:any){ ElMessage.error(e.response?.data?.detail||'重新分析失败') } }
async function loadUsers(){ if(currentUser.value.role!=='admin')return; users.value=(await api.get('/api/v1/users')).data }
async function loadSettings(){ if(currentUser.value.role!=='admin')return; const {data}=await api.get('/api/v1/settings'); settingsForm.masked=data.comfyui_api_key_masked; comfyKeys.value=(await api.get('/api/v1/comfyui-keys')).data }
async function saveSettings(){ if(!settingsForm.comfyui_api_key)return ElMessage.warning('请输入新的 ComfyUI 密钥'); await api.patch('/api/v1/settings',{comfyui_api_key:settingsForm.comfyui_api_key}); settingsForm.comfyui_api_key=''; await loadSettings(); ElMessage.success('默认 ComfyUI 密钥已更新') }
function editComfyKey(item?:any){ Object.assign(comfyKeyForm,item?{...item,key:'',category_ids:[...(item.category_ids||[])]}:{id:0,name:'',key:'',enabled:true,category_ids:[]}); dialogs.comfyKey=true }
async function saveComfyKey(){ if(!comfyKeyForm.name.trim())return ElMessage.warning('请输入密钥名称'); const body:any={name:comfyKeyForm.name,key:comfyKeyForm.key,enabled:comfyKeyForm.enabled,category_ids:comfyKeyForm.category_ids}; if(comfyKeyForm.id&&!comfyKeyForm.key)delete body.key; const response=comfyKeyForm.id?await api.patch(`/api/v1/comfyui-keys/${comfyKeyForm.id}`,body):await api.post('/api/v1/comfyui-keys',body); dialogs.comfyKey=false; await loadSettings(); if(response.data.key)await ElMessageBox.alert(`新密钥只显示一次：\n${response.data.key}`,'请立即复制保存',{confirmButtonText:'知道了'}); ElMessage.success('ComfyUI 密钥已保存') }
async function deleteComfyKey(item:any){ try{await ElMessageBox.confirm(`确定删除密钥「${item.name}」吗？`,'确认删除',{type:'warning'});await api.delete(`/api/v1/comfyui-keys/${item.id}`);await loadSettings()}catch(e:any){if(e!=='cancel')ElMessage.error(e.response?.data?.detail||'删除失败')} }
function handleUserMenu(command:string){ if(command==='logout')logout(); else page.value=command as Page }
function editUser(user?:any){ avatarFile.value=null; Object.assign(userForm,user?{...user,password:'',category_ids:[...user.category_ids]}:{id:0,username:'',password:'',role:'user',enabled:true,avatar_url:'',category_ids:[]}); dialogs.user=true }
function chooseAvatar(e:Event){ const file=(e.target as HTMLInputElement).files?.[0]; if(file)avatarFile.value=file }
async function saveUser(){ if(!userForm.username)return ElMessage.warning('请输入账号名'); if(!userForm.id&&!userForm.password)return ElMessage.warning('请输入初始密码'); const body:any={username:userForm.username,role:userForm.role,enabled:userForm.enabled,category_ids:userForm.category_ids}; if(userForm.password)body.password=userForm.password; let saved:any; if(userForm.id)saved=(await api.patch(`/api/v1/users/${userForm.id}`,body)).data; else saved=(await api.post('/api/v1/users',body)).data; let avatarUrl=saved.avatar_url; if(avatarFile.value){const form=new FormData();form.append('file',avatarFile.value);avatarUrl=(await api.post(`/api/v1/users/${saved.id}/avatar`,form)).data.avatar_url} if(saved.id===currentUser.value.user_id){currentUser.value={...currentUser.value,avatar_url:avatarUrl};localStorage.setItem('vpl_user',JSON.stringify(currentUser.value))} dialogs.user=false; await loadUsers(); ElMessage.success('账号已保存') }
async function deleteUser(user:any){ try{await ElMessageBox.confirm(`确定删除账号「${user.username}」吗？`,'确认删除',{type:'warning'});await api.delete(`/api/v1/users/${user.id}`);await loadUsers()}catch(e:any){if(e!=='cancel')ElMessage.error(e.response?.data?.detail||'删除失败')} }
function openAsset(a:any){ selected.value=JSON.parse(JSON.stringify(a)); drawer.value=true }
async function saveAsset(){ await api.patch(`/api/v1/assets/${selected.value.id}`,{prompt_text:selected.value.prompt_text,category_id:selected.value.category_id}); ElMessage.success('已保存'); drawer.value=false; await loadAssets() }
async function restore(){ await api.post(`/api/v1/assets/${selected.value.id}/restore`); selected.value.prompt_text=selected.value.ai_original_text; ElMessage.success('已恢复 AI 原文') }
async function reanalyze(){ await api.post(`/api/v1/assets/${selected.value.id}/reanalyze`); ElMessage.success('已加入后台分析任务'); drawer.value=false; await loadAssets() }
async function deleteAsset(a=selected.value){ await ElMessageBox.confirm('删除后图片与提示词不可恢复，确定继续吗？','确认删除',{type:'warning'}); await api.delete(`/api/v1/assets/${a.id}`); drawer.value=false; ElMessage.success('已删除'); await loadAssets() }
function chooseFiles(e:Event){ const input=e.target as HTMLInputElement; uploadFiles.value=Array.from(input.files||[]).filter(f=>/\.(jpe?g|png|webp)$/i.test(f.name)); input.value='' }
function pasteImage(e:ClipboardEvent){
  if(!loggedIn.value || page.value!=='assets')return
  const target=e.target
  if(target instanceof HTMLElement&&target.closest('input,textarea,[contenteditable="true"]'))return
  const clipboard=e.clipboardData
  if(!clipboard)return
  // Chrome/Edge 在从截图工具、微信等应用复制图片时，图片通常只出现在
  // DataTransferItem 中，clipboardData.files 可能是空的，因此两种格式都兼容。
  const itemFiles=Array.from(clipboard.items||[])
    .filter(item=>item.kind==='file'&&item.type.startsWith('image/'))
    .map(item=>item.getAsFile())
    .filter((file): file is File=>!!file)
  const files=itemFiles.length?itemFiles:Array.from(clipboard.files||[]).filter(file=>file.type.startsWith('image/'))
  if(files.length){
    e.preventDefault()
    uploadFiles.value.push(...files)
    ElMessage.success(`已加入 ${files.length} 张剪贴板图片`)
  }
}
function chooseUploadProvider(){ uploadForm.model_name=''; const models=availableUploadModels.value; if(models.length===1)uploadForm.model_name=models[0] }
async function upload(force=false){ if(!uploadFiles.value.length) return ElMessage.warning('请先选择图片'); if(!uploadForm.category_id) return ElMessage.warning('请选择素材分类'); if(uploadForm.provider_id&&!uploadForm.model_name)return ElMessage.warning('请选择本次分析使用的模型'); const form=new FormData(); uploadFiles.value.forEach(f=>form.append('files',f)); Object.entries(uploadForm).forEach(([k,v])=>{if(v!==undefined&&v!==null&&v!=='')form.append(k,String(v))}); form.append('force',String(force)); try{ const {data}=await api.post('/api/v1/assets/upload',form); if(data.duplicates.length&&!force){ await ElMessageBox.confirm(`发现 ${data.duplicates.length} 张重复图片。仍然上传吗？`,'重复图片',{confirmButtonText:'仍然上传',cancelButtonText:'跳过',type:'warning'}).then(()=>upload(true)).catch(()=>{}); return } ElMessage.success(`已上传 ${data.items.length} 张，重复 ${data.duplicates.length} 张`); uploadFiles.value=[]; await loadAssets(); page.value='assets' }catch(e:any){ElMessage.error(e.response?.data?.detail||'上传失败')} }
function editCategory(c?:any){ Object.assign(categoryForm,c?{...c}:{id:0,name:'',description:'',sort_order:0,enabled:true}); dialogs.category=true }
async function saveCategory(){ if(categoryForm.id) await api.patch(`/api/v1/categories/${categoryForm.id}`,categoryForm); else await api.post('/api/v1/categories',categoryForm); dialogs.category=false; await loadCategories(); ElMessage.success('分类已保存') }
async function deleteCategory(c:any){ try{await ElMessageBox.confirm('分类必须为空才能删除，确定删除吗？','确认');await api.delete(`/api/v1/categories/${c.id}`);await loadCategories()}catch(e:any){if(e!== 'cancel')ElMessage.error(e.response?.data?.detail||'删除失败')} }
function editProvider(p?:any){ Object.assign(providerForm,p?{id:p.id,name:p.name,base_url:p.base_url,api_key:'',models:[...(p.models||[])],enabled:p.enabled}:{id:0,name:'',base_url:'http://host.docker.internal:1234/v1',api_key:'',models:[],enabled:true}); dialogs.provider=true }
async function saveProvider(){ if(!providerForm.name||!providerForm.base_url)return ElMessage.warning('请填写服务名称和 Base URL'); const body:any={name:providerForm.name,base_url:providerForm.base_url,api_key:providerForm.api_key,models:providerForm.models,enabled:providerForm.enabled}; if(providerForm.id&&!providerForm.api_key)delete body.api_key; if(providerForm.id) await api.patch(`/api/v1/providers/${providerForm.id}`,body); else await api.post('/api/v1/providers',body); dialogs.provider=false; await loadProviders(); ElMessage.success('服务已保存') }
async function pullProviderModels(p:any){ try{const {data}=await api.post(`/api/v1/providers/${p.id}/models/pull`);await loadProviders();ElMessage.success(`已拉取 ${data.count} 个模型`)}catch(e:any){ElMessage.error(e.response?.data?.detail||'拉取模型失败')} }
async function testProvider(p:any){ const {data}=await api.post(`/api/v1/providers/${p.id}/test`); data.ok?ElMessage.success(data.message):ElMessage.error(data.message) }
async function deleteProvider(p:any){ try{await ElMessageBox.confirm('删除后已有素材仍会保留，但无法使用该服务重新分析。确定吗？','确认删除',{type:'warning'});await api.delete(`/api/v1/providers/${p.id}`);await loadProviders()}catch(e:any){if(e!== 'cancel')ElMessage.error(e.response?.data?.detail||'删除失败')} }
async function editProfile(p?:any){ Object.assign(profileForm,p?{...p}:{id:0,name:'',system_prompt:'',temperature:.2,max_tokens:1200,enabled:true}); dialogs.profile=true }
async function saveProfile(){ if(profileForm.id) await api.patch(`/api/v1/prompt-profiles/${profileForm.id}`,profileForm); else await api.post('/api/v1/prompt-profiles',profileForm); dialogs.profile=false; await loadProfiles(); ElMessage.success('模板已保存') }
async function randomize(){ if(!randomForm.category_ids.length)return ElMessage.warning('至少选择一个分类'); randomItems.value=(await api.post('/api/v1/random',randomForm)).data.items }
async function copyText(text:string){ await navigator.clipboard.writeText(text); ElMessage.success('已复制到剪贴板') }
async function downloadFile(url:string, fallbackName:string){ const response=await api.get(url,{responseType:'blob'}); const blobUrl=URL.createObjectURL(response.data); const link=document.createElement('a'); link.href=blobUrl; link.download=fallbackName; link.click(); URL.revokeObjectURL(blobUrl) }
function downloadBackup(){ downloadFile('/api/v1/backup','visual-prompt-library-backup.zip') }
function exportCategory(id:number){ downloadFile(`/api/v1/export?category_id=${id}`,`category-${id}.json`) }
onMounted(()=>{document.addEventListener('paste',pasteImage); window.addEventListener('vpl-auth-expired',handleAuthExpired); if(loggedIn.value)bootstrap()}); onUnmounted(()=>{document.removeEventListener('paste',pasteImage); window.removeEventListener('vpl-auth-expired',handleAuthExpired)})
</script>

<template>
  <div v-if="!loggedIn" class="login-page"><div class="login-card"><div class="brand-mark">✦</div><h1>AI Prompt Library</h1><p>视觉反推提示词素材库</p><el-form @submit.prevent="login"><el-form-item><el-input v-model="loginForm.username" size="large" placeholder="管理员账号" /></el-form-item><el-form-item><el-input v-model="loginForm.password" size="large" type="password" show-password placeholder="管理员密码" /></el-form-item><el-button class="login-btn" :loading="loading" type="primary" size="large" @click="login">进入素材库</el-button></el-form><small>首次使用请在 .env 中修改 ADMIN_PASSWORD</small></div></div>
  <div v-else class="shell">
    <aside class="sidebar"><div class="logo"><span>✦</span><div><b>AI Prompt</b><small>LIBRARY</small></div></div><nav><button v-for="item in visibleNav" :key="item.id" :class="{active:page===item.id}" @click="page=item.id as Page"><component :is="item.icon"/><span>{{item.label}}</span></button></nav><div class="sidebar-bottom"><div class="status-dot"><i/>系统运行正常</div><button class="logout" @click="logout">退出登录</button></div></aside>
    <main class="main"><header class="topbar"><div><span class="eyebrow">工作台 / {{currentLabel}}</span><h2>{{currentLabel}}</h2></div><div class="top-actions"><el-button class="top-refresh" circle @click="bootstrap" title="刷新数据"><el-icon><RefreshRight/></el-icon></el-button><el-dropdown trigger="click" @command="handleUserMenu"><div class="profile-chip"><div class="user-avatar"><img v-if="currentUser.avatar_url" :src="imageUrl(currentUser.avatar_url)"/><span v-else>{{(currentUser.username||'A').slice(0,1).toUpperCase()}}</span></div><div class="profile-copy"><b>{{currentUser.username}}</b><small>{{currentUser.role==='admin'?'管理员':'普通账号'}}</small></div><ArrowDown class="profile-arrow"/></div><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="currentUser.role==='admin'" command="users"><User/> 账号管理</el-dropdown-item><el-dropdown-item v-if="currentUser.role==='admin'" command="settings"><Setting/> 系统设置</el-dropdown-item><el-dropdown-item divided command="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
      <section ref="contentRef" class="content" @scroll="handleContentScroll">
        <template v-if="page==='dashboard'"><div class="hero"><div><span class="eyebrow light">WELCOME BACK</span><h1>让每一张图，<em>都变成灵感。</em></h1><p>集中管理视觉素材与 AI 反推提示词，让创作从这里开始。</p><el-button type="primary" @click="page='assets'">浏览素材库 <el-icon><Picture/></el-icon></el-button></div><div class="hero-orb">✦</div></div><div class="stat-grid"><div class="stat-card"><span>素材总数</span><strong>{{total}}</strong><i><Picture/></i></div><div class="stat-card"><span>启用分类</span><strong>{{categories.filter(c=>c.enabled).length}}</strong><i><Collection/></i></div><div class="stat-card"><span>AI 服务</span><strong>{{providers.filter(p=>p.enabled).length}}</strong><i><Connection/></i></div><div class="stat-card"><span>分析模板</span><strong>{{profiles.length}}</strong><i><Files/></i></div></div><div v-if="currentUser.role==='admin'" class="progress-card"><div class="progress-heading"><div><span class="eyebrow">BACKGROUND WORKER</span><h3>分析任务进度</h3><p>{{jobProgress.active ? `还有 ${jobProgress.active} 个任务正在处理` : '当前没有排队中的任务'}}</p></div><strong>{{jobProgress.percentage}}%</strong></div><div v-if="jobProgress.current" class="current-job"><img :src="imageUrl(jobProgress.current.thumbnail_url)"/><div class="current-job-copy"><span class="eyebrow">当前分析素材</span><b>{{jobProgress.current.original_filename || `素材 #${jobProgress.current.asset_id}`}}</b><small>{{jobProgress.current.category_name}} · {{jobProgress.current.status==='processing'?'运行中':'排队中'}}</small></div><el-tag type="warning" effect="dark">{{jobProgress.current.status==='processing'?'运行中':'排队中'}}</el-tag></div><el-progress :percentage="jobProgress.percentage" :stroke-width="10" :status="jobProgress.failed && !jobProgress.active ? 'exception' : undefined"/><div class="progress-counts"><span><i class="dot completed"/>已完成 {{jobProgress.completed}}</span><span><i class="dot active"/>进行中 {{jobProgress.active}}</span><span><i class="dot failed"/>失败 {{jobProgress.failed}}</span></div></div><div v-if="currentUser.role=== 'admin' && failedJobs.length" class="failed-jobs"><div class="failed-jobs-heading"><div><h3>失败图片</h3><p>可直接定位并重新分析，不会影响后续任务。</p></div><el-button text type="primary" @click="page='jobs'">查看任务列表 →</el-button></div><div class="failed-job-list"><div v-for="job in failedJobs" :key="job.id" class="failed-job"><img :src="imageUrl(job.thumbnail_url)"/><div class="failed-job-copy"><b>{{job.original_filename || `素材 #${job.asset_id}`}}</b><small>{{job.category_name}} · {{job.error_message || '分析失败'}}</small></div><el-button type="warning" plain size="small" @click="reanalyzeJob(job)">重新分析</el-button></div></div></div><div class="section-head"><div><h3>最近素材</h3><p>最新加入的视觉灵感</p></div><el-button text type="primary" @click="page='assets'">查看全部 →</el-button></div><div class="asset-grid compact"><div v-for="a in assets.slice(0,6)" :key="a.id" class="asset-card" @click="openAsset(a)"><img :src="imageUrl(a.thumbnail_url)"/><div class="asset-meta"><b>#{{a.id}}</b><span>{{a.category_name}}</span></div></div><div v-if="!assets.length" class="empty">还没有素材，去上传第一张图片吧</div></div></template>
        <template v-else-if="page==='assets'"><div class="page-toolbar"><div><h3>素材库</h3><p>每张图片对应一条完整的 AI 反推提示词</p></div><div class="toolbar-actions"><el-input v-model="filters.search" clearable placeholder="搜索文件名或提示词" @keyup.enter="loadAssets"><template #prefix><Search/></template></el-input><el-select v-model="filters.category_id" clearable placeholder="全部分类" @change="changeAssetCategory"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button type="primary" @click="uploadRef?.click()"><Upload/> 上传素材</el-button><el-button @click="folderRef?.click()"><FolderOpened/> 文件夹</el-button><span class="paste-tip">支持 Ctrl + V 粘贴图片</span><input ref="uploadRef" hidden type="file" multiple accept=".jpg,.jpeg,.png,.webp" @change="chooseFiles"/><input ref="folderRef" hidden type="file" multiple webkitdirectory directory accept=".jpg,.jpeg,.png,.webp" @change="chooseFiles"/></div></div><div v-if="uploadFiles.length" class="upload-strip"><b>待上传 {{uploadFiles.length}} 张</b><el-select v-model="uploadForm.category_id" placeholder="素材分类"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="uploadForm.provider_id" clearable placeholder="AI 服务" @change="chooseUploadProvider"><el-option v-for="p in providers.filter(item=>item.enabled)" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-select v-if="uploadForm.provider_id" v-model="uploadForm.model_name" filterable placeholder="本次使用的模型"><el-option v-for="model in availableUploadModels" :key="model" :label="model" :value="model"/></el-select><el-select v-model="uploadForm.prompt_profile_id" clearable placeholder="视觉分析模板"><el-option v-for="p in profiles" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-button type="primary" @click="upload()">开始上传并分析</el-button><el-button @click="uploadFiles=[]">清空</el-button></div><div class="asset-grid"><div v-for="a in assets" :key="a.id" class="asset-card" @click="openAsset(a)"><div class="thumb-wrap"><img :src="imageUrl(a.thumbnail_url)"/><span :class="['status',a.status]">{{a.status==='completed'?'已完成':a.status==='failed'?'失败':a.status==='processing'?'分析中':'排队中'}}</span></div><div class="asset-meta"><b>#{{a.id}}</b><span>{{a.category_name}}</span><small>{{a.original_filename}}</small></div></div><div v-if="!assets.length" class="empty">暂无素材。支持拖拽、批量选择、文件夹选择和 Ctrl + V 粘贴图片。</div></div><div class="asset-load-more"><span v-if="assetsLoading">正在加载更多素材…</span><span v-else-if="assetsHasMore">下拉继续加载</span><span v-else>已显示全部 {{total}} 张素材</span></div></template>
        <template v-else-if="page==='random'"><div class="page-toolbar"><div><h3>随机提示词</h3><p>从多个分类的候选池中，随机抽取完整提示词，不做拼接。</p></div></div><div class="random-panel"><div class="form-label">候选分类</div><el-select v-model="randomForm.category_ids" multiple collapse-tags placeholder="选择一个或多个分类"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><div class="random-row"><label>抽取数量 <el-input-number v-model="randomForm.count" :min="1" :max="100"/></label><label>Seed <el-input-number v-model="randomForm.seed" :min="0" :max="999999999"/></label><el-button type="primary" size="large" @click="randomize"><MagicStick/> 开始抽取</el-button></div></div><div class="result-list"><div v-for="item in randomItems" :key="item.asset_id" class="result-card"><img :src="imageUrl(item.thumbnail_url)"/><div><span class="eyebrow">#{{item.asset_id}} · {{item.category_name}}</span><p>{{item.prompt}}</p></div><el-button circle @click="copyText(item.prompt)"><CopyDocument/></el-button></div><div v-if="!randomItems.length" class="empty">选择分类并开始抽取，结果会显示在这里</div></div></template>
        <template v-else-if="page==='categories'"><div class="page-toolbar"><div><h3>分类管理</h3><p>分类由你定义，图片文件不会因改名而移动。</p></div><el-button type="primary" @click="editCategory()"><Plus/> 新增分类</el-button></div><div class="table-card"><el-table :data="categories" stripe><el-table-column prop="name" label="分类名称"/><el-table-column prop="description" label="描述"/><el-table-column prop="asset_count" label="素材数" width="100"/><el-table-column prop="sort_order" label="排序" width="80"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="editCategory(s.row)"><Edit/></el-button><el-button link type="danger" @click="deleteCategory(s.row)"><Delete/></el-button></template></el-table-column></el-table></div></template>
        <template v-else-if="page==='providers'"><div class="page-toolbar"><div><h3>AI 服务管理</h3><p>每个服务可拉取或手动添加多个模型，上传素材时再选择本次使用的模型。</p></div><el-button type="primary" @click="editProvider()"><Plus/> 新增服务</el-button></div><div class="provider-grid"><div v-for="p in providers" :key="p.id" class="provider-card"><div class="provider-icon"><Connection/></div><div class="provider-info"><h4>{{p.name}} <el-tag size="small" :type="p.enabled?'success':'info'">{{p.enabled?'已启用':'已停用'}}</el-tag></h4><p>{{p.base_url}}</p><div class="provider-models"><el-tag v-for="model in p.models" :key="model" size="small" effect="plain">{{model}}</el-tag><span v-if="!p.models.length" class="muted">尚未添加模型</span></div><small>{{p.models.length}} 个模型 · {{p.api_key_masked||'未设置 Key'}}</small></div><div class="card-actions"><el-button link type="primary" @click="pullProviderModels(p)"><Refresh/> 拉取模型</el-button><el-button link @click="testProvider(p)">测试连接</el-button><el-button link @click="editProvider(p)">编辑</el-button><el-button link type="danger" @click="deleteProvider(p)">删除</el-button></div></div><div v-if="!providers.length" class="empty">尚未配置 AI 服务</div></div></template>
        <template v-else-if="page==='profiles'"><div class="page-toolbar"><div><h3>系统提示词模板</h3><p>后台可编辑的视觉分析专家指令，决定 AI 的输出风格。</p></div><el-button type="primary" @click="editProfile()"><Plus/> 新增模板</el-button></div><div class="profile-list"><div v-for="p in profiles" :key="p.id" class="profile-card"><div><h4>{{p.name}} <el-tag size="small">{{p.enabled?'启用':'停用'}}</el-tag></h4><p>{{p.system_prompt.slice(0,180)}}{{p.system_prompt.length>180?'…':''}}</p><small>temperature {{p.temperature}} · max tokens {{p.max_tokens}}</small></div><el-button @click="editProfile(p)">编辑模板</el-button></div></div></template>
        <template v-else-if="page==='jobs'"><div class="page-toolbar"><div><h3>分析任务</h3><p>上传请求立即返回，视觉分析在后台队列中执行。</p></div><el-button @click="loadJobs"><Refresh/> 刷新</el-button></div><div class="table-card"><el-table :data="jobs" stripe><el-table-column prop="id" label="任务" width="80"/><el-table-column prop="asset_id" label="素材 ID" width="100"/><el-table-column prop="status" label="状态"/><el-table-column prop="error_message" label="错误信息"/><el-table-column label="操作" width="120"><template #default="s"><el-button v-if="s.row.status==='failed'" link type="warning" @click="reanalyzeJob(s.row)">重新分析</el-button></template></el-table-column><el-table-column prop="created_at" label="创建时间"/></el-table></div></template>
        <template v-else-if="page==='users'"><div class="page-toolbar"><div><h3>账号管理</h3><p>新增账号并控制每个账号可以看到的素材分类。</p></div><el-button type="primary" @click="editUser()"><Plus/> 新增账号</el-button></div><div class="table-card"><el-table :data="users" stripe><el-table-column label="账号" min-width="180"><template #default="s"><div class="user-cell"><div class="mini-avatar"><img v-if="s.row.avatar_url" :src="imageUrl(s.row.avatar_url)"/><span v-else>{{s.row.username.slice(0,1).toUpperCase()}}</span></div><b>{{s.row.username}}</b></div></template></el-table-column><el-table-column label="角色" width="110"><template #default="s"><el-tag :type="s.row.role==='admin'?'warning':'info'">{{s.row.role==='admin'?'管理员':'普通账号'}}</el-tag></template></el-table-column><el-table-column label="可见分类" min-width="260"><template #default="s"><span v-if="s.row.role==='admin'" class="muted">全部分类</span><el-tag v-for="name in s.row.category_names" v-else :key="name" size="small" class="category-tag">{{name}}</el-tag><span v-if="s.row.role!=='admin'&&!s.row.category_names.length" class="muted">未分配</span></template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="editUser(s.row)"><Edit/> 编辑</el-button><el-button link type="danger" @click="deleteUser(s.row)"><Delete/></el-button></template></el-table-column></el-table></div></template>
        <template v-else-if="page==='settings'"><div class="page-toolbar"><div><h3>系统设置</h3><p>管理多个 ComfyUI 访问密钥，并限制每个密钥可访问的素材分类。</p></div><el-button type="primary" @click="editComfyKey()"><Plus/> 新增密钥</el-button></div><div class="settings-card legacy-key"><div class="settings-icon"><Key/></div><div class="settings-copy"><h3>默认兼容密钥</h3><p>当前密钥：<code>{{settingsForm.masked||'未设置'}}</code></p><small>兼容旧版部署，默认可访问全部分类。新工作流建议使用下方独立密钥。</small></div><el-input v-model="settingsForm.comfyui_api_key" type="password" show-password placeholder="输入新的默认密钥"/><el-button type="primary" @click="saveSettings">更新默认密钥</el-button></div><div class="table-card comfy-key-table"><el-table :data="comfyKeys" stripe><el-table-column prop="name" label="密钥名称" min-width="180"/><el-table-column prop="key_masked" label="密钥" min-width="180"><template #default="s"><code>{{s.row.key_masked}}</code></template></el-table-column><el-table-column label="可访问分类" min-width="260"><template #default="s"><el-tag v-if="s.row.all_categories" type="success">全部分类</el-tag><template v-else><el-tag v-for="name in s.row.category_names" :key="name" size="small" class="category-tag">{{name}}</el-tag></template></template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="editComfyKey(s.row)"><Edit/> 编辑</el-button><el-button v-if="s.row.name!=='默认 ComfyUI 密钥'" link type="danger" @click="deleteComfyKey(s.row)"><Delete/></el-button></template></el-table-column></el-table></div></template>
        <template v-else><div class="page-toolbar"><div><h3>导入导出</h3><p>备份 SQLite 数据库与图片，或导出指定分类的 JSON。</p></div></div><div class="backup-card"><Download/><div><h4>完整数据备份</h4><p>包含 SQLite 数据库、原图与缩略图的 ZIP 文件。</p></div><el-button type="primary" @click="downloadBackup">下载备份</el-button></div><div class="backup-card" v-for="c in categories" :key="c.id"><Files/><div><h4>导出「{{c.name}}」</h4><p>导出该分类的素材 ID、分类名、完整提示词与图片路径。</p></div><el-button @click="exportCategory(c.id)">下载 JSON</el-button></div></template>
      </section>
    </main>
    <el-drawer v-model="drawer" title="素材详情" size="520px"><div v-if="selected" class="detail"><img class="detail-image" :src="imageUrl(selected.image_url)"/><div class="detail-tags"><el-tag>#{{selected.id}}</el-tag><el-tag type="info">{{selected.category_name}}</el-tag><el-tag :type="selected.status==='completed'?'success':'warning'">{{selected.status}}</el-tag></div><div class="detail-info"><span>原始文件名 <b>{{selected.original_filename}}</b></span><span>尺寸 <b>{{selected.width}} × {{selected.height}}</b></span><span>模型 <b>{{selected.model_name||'未配置'}}</b></span></div><h4>移动分类</h4><el-select v-model="selected.category_id" style="width:100%"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><h4>AI 原始分析</h4><div class="readonly-text">{{selected.ai_original_text||'等待后台分析结果…'}}</div><h4>当前提示词 <el-button link type="primary" @click="restore">恢复 AI 原文</el-button></h4><el-input v-model="selected.prompt_text" type="textarea" :rows="10"/><div class="drawer-actions"><el-button @click="copyText(selected.prompt_text)"><CopyDocument/>复制</el-button><el-button type="primary" @click="saveAsset">保存修改</el-button><el-button @click="reanalyze">重新分析</el-button><el-button type="danger" plain @click="deleteAsset()">删除</el-button></div></div></el-drawer>
    <el-dialog v-model="dialogs.category" :title="categoryForm.id?'编辑分类':'新增分类'" width="440px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="categoryForm.name"/></el-form-item><el-form-item label="描述"><el-input v-model="categoryForm.description"/></el-form-item><el-form-item label="排序"><el-input-number v-model="categoryForm.sort_order"/></el-form-item><el-form-item label="启用"><el-switch v-model="categoryForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialogs.category=false">取消</el-button><el-button type="primary" @click="saveCategory">保存</el-button></template></el-dialog>
    <el-dialog v-model="dialogs.provider" :title="providerForm.id?'编辑 AI 服务':'新增 AI 服务'" width="560px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="providerForm.name"/></el-form-item><el-form-item label="Base URL"><el-input v-model="providerForm.base_url" placeholder="http://host.docker.internal:1234/v1"/></el-form-item><el-form-item label="API Key"><el-input v-model="providerForm.api_key" type="password" show-password placeholder="留空则保持原 Key"/></el-form-item><el-form-item label="模型列表"><el-select v-model="providerForm.models" multiple filterable allow-create default-first-option style="width:100%" placeholder="可手动输入模型名称"><el-option v-for="model in providerForm.models" :key="model" :label="model" :value="model"/></el-select><small class="form-help">保存后可在服务卡片点击“拉取模型”，自动从 /models 获取并更新列表。</small></el-form-item><el-form-item label="启用"><el-switch v-model="providerForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialogs.provider=false">取消</el-button><el-button type="primary" @click="saveProvider">保存</el-button></template></el-dialog>
    <el-dialog v-model="dialogs.profile" :title="profileForm.id?'编辑提示词模板':'新增提示词模板'" width="700px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="profileForm.name"/></el-form-item><el-form-item label="System Prompt"><el-input v-model="profileForm.system_prompt" type="textarea" :rows="14"/></el-form-item><div class="inline-fields"><el-form-item label="Temperature"><el-input-number v-model="profileForm.temperature" :min="0" :max="2" :step=".1"/></el-form-item><el-form-item label="Max Tokens"><el-input-number v-model="profileForm.max_tokens" :min="100" :max="8000"/></el-form-item><el-form-item label="启用"><el-switch v-model="profileForm.enabled"/></el-form-item></div></el-form><template #footer><el-button @click="dialogs.profile=false">取消</el-button><el-button type="primary" @click="saveProfile">保存</el-button></template></el-dialog>
    <el-dialog v-model="dialogs.user" :title="userForm.id?'编辑账号':'新增账号'" width="560px"><el-form label-position="top"><el-form-item label="头像"><div class="avatar-editor"><div class="avatar-preview"><img v-if="avatarFile" :src="URL.createObjectURL(avatarFile)"/><img v-else-if="userForm.avatar_url" :src="imageUrl(userForm.avatar_url)"/><span v-else>{{(userForm.username||'A').slice(0,1).toUpperCase()}}</span></div><div><el-button @click="avatarRef?.click()"><Upload/> 上传头像</el-button><small>支持 JPG、PNG、WEBP，自动裁剪为 256px。</small></div><input ref="avatarRef" hidden type="file" accept=".jpg,.jpeg,.png,.webp" @change="chooseAvatar"/></div></el-form-item><el-form-item label="账号名"><el-input v-model="userForm.username" :disabled="!!userForm.id" placeholder="例如：designer"/></el-form-item><el-form-item :label="userForm.id?'重置密码（留空不修改）':'初始密码'"><el-input v-model="userForm.password" type="password" show-password placeholder="至少 6 位"/></el-form-item><div class="inline-fields"><el-form-item label="角色"><el-select v-model="userForm.role"><el-option label="普通账号" value="user"/><el-option label="管理员" value="admin"/></el-select></el-form-item><el-form-item label="状态"><el-switch v-model="userForm.enabled"/></el-form-item></div><el-form-item v-if="userForm.role==='user'" label="可见分类"><el-select v-model="userForm.category_ids" multiple collapse-tags style="width:100%" placeholder="选择该账号可见的分类"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-alert v-else title="管理员默认可以看到全部分类" type="info" :closable="false"/></el-form><template #footer><el-button @click="dialogs.user=false">取消</el-button><el-button type="primary" @click="saveUser">保存账号</el-button></template></el-dialog>
    <el-dialog v-model="dialogs.comfyKey" :title="comfyKeyForm.id?'编辑 ComfyUI 密钥':'新增 ComfyUI 密钥'" width="560px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="comfyKeyForm.name" placeholder="例如：工作流 A"/></el-form-item><el-form-item :label="comfyKeyForm.id?'新密钥（留空不修改）':'密钥（留空自动生成）'"><el-input v-model="comfyKeyForm.key" type="password" show-password placeholder="建议使用随机长密钥"/></el-form-item><el-form-item label="可访问分类"><el-select v-model="comfyKeyForm.category_ids" multiple collapse-tags style="width:100%" placeholder="不选择表示可访问全部分类"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><small class="form-help">留空代表全部分类；选择后，该密钥只能读取这些分类及其素材。</small></el-form-item><el-form-item label="启用"><el-switch v-model="comfyKeyForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialogs.comfyKey=false">取消</el-button><el-button type="primary" @click="saveComfyKey">保存密钥</el-button></template></el-dialog>
  </div>
</template>
